import{_ as a,o as t,c as r,ag as o}from"./chunks/framework.DAaBRV8r.js";const i="/noc/retire-bw.png",u=JSON.parse(`{"title":"It's time!","description":"","frontmatter":{"layout":"doc","title":"It's time!","date":"2026-10-01T00:00:00.000Z"},"headers":[],"relativePath":"retire.md","filePath":"retire.md"}`),s={name:"retire.md"};function n(l,e,h,m,d,p){return t(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="it-s-time" tabindex="-1">It&#39;s time! <a class="header-anchor" href="#it-s-time" aria-label="Permalink to &quot;It&#39;s time!&quot;">​</a></h1><h3 id="dear-colleagues" tabindex="-1">Dear Colleagues, <a class="header-anchor" href="#dear-colleagues" aria-label="Permalink to &quot;Dear Colleagues,&quot;">​</a></h3><p>After much thought and reflection, I would like to share with you that I have decided to retire by the end of this year.</p><p>I have spent many years away from home, and the past 20 years in Qatar have been a particularly meaningful chapter of my life. I am deeply grateful for the experiences, challenges, achievements, friendships, and memories that have made Qatar feel like home.</p><p>Now, I feel it is time to return home and spend more time with family, especially our aging mother and mother-in-law. Life reminds us that some moments and relationships cannot be postponed.</p><p>As I close this chapter, I sincerely thank you all for your friendship, support, and cooperation over the years. It has been a privilege to work alongside you, and I will always treasure the friendships and memories we have shared.</p><p>Retirement is a new beginning, but saying goodbye is never easy. I hope our paths will cross again and that our friendships will continue.</p><p>I wish you and your families happiness, good health, and success.</p><h3 id="a-few-words-to-remember" tabindex="-1"><a href="/noc/memwall.html">A Few Words to Remember</a> <a class="header-anchor" href="#a-few-words-to-remember" aria-label="Permalink to &quot;[A Few Words to Remember](/memwall)&quot;">​</a></h3><p>As I begin this new chapter, I would be grateful if you could leave a message on my <a href="/noc/memwall.html">Memory Wall</a>. Your words will be a lasting reminder of the people and friendships that made this journey special.</p><p>Thank you for being part of my story.</p><p>With warmest regards,</p><p><img src="'+i+'" alt="retire in black and white"></p><p>Bao Ngo</p>',14)])])}const f=a(s,[["render",n]]);export{u as __pageData,f as default};
